CREATE TABLE `explicacion_prediccion` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `prediccion_id` bigint unsigned NOT NULL,
  `variables` text COLLATE utf8mb4_unicode_ci,
  `variable` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `peso` decimal(8,4) NOT NULL,
  `impacto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `explicacion_prediccion_prediccion_id_foreign` (`prediccion_id`),
  CONSTRAINT `explicacion_prediccion_prediccion_id_foreign` FOREIGN KEY (`prediccion_id`) REFERENCES `predicciones_clinicas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
