  `prediccion_id` bigint unsigned DEFAULT NULL,
  `concepto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `monto` decimal(12,2) NOT NULL,
  `metodo_pago` enum('efectivo','transferencia','pendiente') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `pagado` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `honorarios_medicos_doctor_id_foreign` (`doctor_id`),
  KEY `honorarios_medicos_prediccion_id_foreign` (`prediccion_id`),
  KEY `honorarios_medicos_patient_id_index` (`patient_id`),
  CONSTRAINT `honorarios_medicos_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `honorarios_medicos_prediccion_id_foreign` FOREIGN KEY (`prediccion_id`) REFERENCES `predicciones_clinicas` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
