  `diagnosis` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `treatment` text COLLATE utf8mb4_unicode_ci,
  `assigned_doctor_id` bigint unsigned DEFAULT NULL,
  `assigned_nurse_id` bigint unsigned DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `hospitalizations_triage_id_foreign` (`triage_id`),
  KEY `hospitalizations_bed_id_foreign` (`bed_id`),
  KEY `hospitalizations_assigned_doctor_id_foreign` (`assigned_doctor_id`),
  KEY `hospitalizations_assigned_nurse_id_foreign` (`assigned_nurse_id`),
  CONSTRAINT `hospitalizations_assigned_doctor_id_foreign` FOREIGN KEY (`assigned_doctor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `hospitalizations_assigned_nurse_id_foreign` FOREIGN KEY (`assigned_nurse_id`) REFERENCES `users` (`id`),
  CONSTRAINT `hospitalizations_bed_id_foreign` FOREIGN KEY (`bed_id`) REFERENCES `beds` (`id`),
  CONSTRAINT `hospitalizations_triage_id_foreign` FOREIGN KEY (`triage_id`) REFERENCES `triages` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
