/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medical_alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vital_sign_id` bigint unsigned DEFAULT NULL,
  `triage_id` bigint unsigned DEFAULT NULL,
  `patient_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` enum('Signos Vitales','Medicamento','Hospitalización','Triage','Sistema') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Signos Vitales',
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT '0',
  `triggered_by` bigint unsigned NOT NULL,
  `target_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `medical_alerts_vital_sign_id_foreign` (`vital_sign_id`),
  KEY `medical_alerts_triggered_by_foreign` (`triggered_by`),
  KEY `medical_alerts_target_user_id_foreign` (`target_user_id`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_triage_id` (`triage_id`),
  CONSTRAINT `medical_alerts_target_user_id_foreign` FOREIGN KEY (`target_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `medical_alerts_triage_id_foreign` FOREIGN KEY (`triage_id`) REFERENCES `triages` (`id`),
  CONSTRAINT `medical_alerts_triggered_by_foreign` FOREIGN KEY (`triggered_by`) REFERENCES `users` (`id`),
  CONSTRAINT `medical_alerts_vital_sign_id_foreign` FOREIGN KEY (`vital_sign_id`) REFERENCES `vital_signs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=159 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
