-- Table structure for table `patient_deaths`
--

DROP TABLE IF EXISTS `patient_deaths`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patient_deaths` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `triage_id` bigint unsigned NOT NULL,
  `doctor_id` bigint unsigned NOT NULL,
  `bed_id` bigint unsigned DEFAULT NULL,
  `death_time` datetime NOT NULL,
  `cause_of_death` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `immediate_cause` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clinical_summary` text COLLATE utf8mb4_unicode_ci,
  `autopsy_required` tinyint(1) NOT NULL DEFAULT '0',
  `death_certificate_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notified_family` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'No',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_deaths_triage_id_foreign` (`triage_id`),
  KEY `patient_deaths_doctor_id_foreign` (`doctor_id`),
  CONSTRAINT `patient_deaths_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `patient_deaths_triage_id_foreign` FOREIGN KEY (`triage_id`) REFERENCES `triages` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

