--
-- Table structure for table `triages`
--

DROP TABLE IF EXISTS `triages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `triages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `patient_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `age` int NOT NULL,
  `triage_level` enum('Rojo','Naranja','Amarillo','Verde','Azul') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Verde',
  `symptoms` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('En Espera','En Atención','Hospitalizado','Derivado','Dado de Alta') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'En Espera',
  `assigned_area` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Urgencias',
  `vitals_ta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vitals_fc` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vitals_temp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vitals_spo2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_derived` tinyint(1) NOT NULL DEFAULT '0',
  `derivation_hospital` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `diagnostico` text COLLATE utf8mb4_unicode_ci,
  `cie10` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tratamiento` text COLLATE utf8mb4_unicode_ci,
  `doctor_notes` text COLLATE utf8mb4_unicode_ci,
  `assigned_doctor` bigint unsigned DEFAULT NULL,
  `discharge_date` datetime DEFAULT NULL,
  `discharge_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discharge_doctor_id` bigint unsigned DEFAULT NULL,
  `discharge_notes` text COLLATE utf8mb4_unicode_ci,
  `assigned_doctor_id` bigint unsigned DEFAULT NULL,
  `ia_nivel` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'Verde',
  `ia_clase` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Estable',
  `ia_validation` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'VP,VN,FP,FN',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_triage_level` (`triage_level`),
  KEY `idx_status_level` (`status`,`triage_level`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=50180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

