CREATE TABLE `vital_signs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `triage_id` bigint unsigned NOT NULL,
  `patient_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
