  `weight` decimal(5,2) DEFAULT NULL,
  `height` decimal(5,2) DEFAULT NULL,
  `glucose` decimal(5,1) DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `recorded_by` bigint unsigned NOT NULL,
  `is_critical` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vital_signs_recorded_by_foreign` (`recorded_by`),
  KEY `idx_triage_id` (`triage_id`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `vital_signs_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `vital_signs_triage_id_foreign` FOREIGN KEY (`triage_id`) REFERENCES `triages` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6622 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
